document.addEventListener('DOMContentLoaded', function() {
  const menuToggle = document.getElementById('menuToggle');
  const navMenu = document.getElementById('navMenu');
  
  if (menuToggle && navMenu) {
    menuToggle.addEventListener('click', function() {
      const expanded = menuToggle.getAttribute('aria-expanded') === 'true';
      menuToggle.setAttribute('aria-expanded', !expanded);
      navMenu.classList.toggle('open');
    });

    const navLinks = navMenu.querySelectorAll('.nav-link');
    navLinks.forEach(function(link) {
      link.addEventListener('click', function() {
        menuToggle.setAttribute('aria-expanded', 'false');
        navMenu.classList.remove('open');
      });
    });
  }

  const reveals = document.querySelectorAll('.reveal-on-scroll');
  if ('IntersectionObserver' in window) {
    const observer = new IntersectionObserver(function(entries) {
      entries.forEach(function(entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add('revealed');
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.15 });

    reveals.forEach(function(el) {
      observer.observe(el);
    });
  } else {
    reveals.forEach(function(el) {
      el.classList.add('revealed');
    });
  }

  const statValues = document.querySelectorAll('.stat-val');
  let statsTriggered = false;

  function animateCounters() {
    if (statsTriggered) return;
    statsTriggered = true;

    statValues.forEach(function(el) {
      const target = parseInt(el.getAttribute('data-target'), 10);
      let current = 0;
      const stepTime = Math.max(20, Math.floor(1500 / target));
      const timer = setInterval(function() {
        current += 1;
        el.textContent = current;
        if (current >= target) {
          el.textContent = target;
          clearInterval(timer);
        }
      }, stepTime);
    });
  }

  const statsSection = document.querySelector('.stats-ribbon');
  if (statsSection && 'IntersectionObserver' in window) {
    const statsObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(entry) {
        if (entry.isIntersecting) {
          animateCounters();
          statsObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.25 });
    statsObserver.observe(statsSection);
  } else {
    animateCounters();
  }

  const searchInput = document.getElementById('catalogSearch');
  const filterPills = document.querySelectorAll('.filter-pill');
  const catalogCards = document.querySelectorAll('.catalog-item');
  const itemCountEl = document.getElementById('itemCount');

  let currentCategory = 'all';
  let searchQuery = '';

  function filterCatalog() {
    let visibleCount = 0;
    const query = searchQuery.trim().toLowerCase();

    catalogCards.forEach(function(card) {
      const cardCategory = card.getAttribute('data-category') || '';
      const text = card.textContent.toLowerCase();
      
      const matchesCategory = (currentCategory === 'all') || (cardCategory === currentCategory);
      const matchesSearch = (!query) || text.includes(query);

      if (matchesCategory && matchesSearch) {
        card.style.display = '';
        visibleCount++;
      } else {
        card.style.display = 'none';
      }
    });

    if (itemCountEl) {
      itemCountEl.textContent = 'Zobrazeno ' + visibleCount + ' položek';
    }
  }

  filterPills.forEach(function(pill) {
    pill.addEventListener('click', function() {
      filterPills.forEach(function(p) { p.classList.remove('active'); });
      pill.classList.add('active');
      currentCategory = pill.getAttribute('data-filter') || 'all';
      filterCatalog();
    });
  });

  if (searchInput) {
    searchInput.addEventListener('input', function(e) {
      searchQuery = e.target.value;
      filterCatalog();
    });
  }

  const modalBackdrop = document.getElementById('techModalBackdrop');
  const modalClose = document.getElementById('techModalClose');
  const modalCloseSecondary = document.getElementById('modalCloseSecondary');
  const modalTitle = document.getElementById('modalTitle');
  const modalNorm = document.getElementById('modalNorm');
  const modalImg = document.getElementById('modalImg');
  const modalDesc = document.getElementById('modalDesc');
  const modalMaterials = document.getElementById('modalMaterials');
  const modalTolerances = document.getElementById('modalTolerances');
  const modalSurface = document.getElementById('modalSurface');
  const modalTableHead = document.getElementById('modalTableHead');
  const modalTableBody = document.getElementById('modalTableBody');
  const modalPoptatBtn = document.getElementById('modalPoptatBtn');

  function openTechModal(productId) {
    const item = catalogData.find(function(it) { return it.id === productId; });
    if (!item) return;

    modalTitle.textContent = item.title;
    modalNorm.textContent = item.norm;
    modalImg.src = item.image;
    modalImg.alt = item.title;
    modalDesc.textContent = item.description;
    modalTolerances.textContent = item.tolerances;
    modalSurface.textContent = item.surface;

    modalMaterials.innerHTML = '';
    item.materials.forEach(function(mat) {
      const span = document.createElement('span');
      span.className = 'mat-badge';
      span.textContent = mat;
      modalMaterials.appendChild(span);
    });

    modalTableHead.innerHTML = '';
    modalTableBody.innerHTML = '';

    if (item.specs && item.specs.length > 0) {
      const sample = item.specs[0];
      const keys = Object.keys(sample);

      const headerTr = document.createElement('tr');
      keys.forEach(function(k) {
        const th = document.createElement('th');
        if (k === 'd') th.textContent = 'Jmenovitý průměr (d)';
        else if (k === 'dk') th.textContent = 'Průměr hlavy (dk)';
        else if (k === 'k') th.textContent = 'Výška hlavy (k)';
        else if (k === 'r') th.textContent = 'Poloměr zaoblení (r)';
        else if (k === 'l') th.textContent = 'Rozsah délek (l)';
        else if (k === 'd1') th.textContent = 'Průměr dutiny (d1)';
        else if (k === 't') th.textContent = 'Hloubka dutiny (t)';
        else if (k === 's') th.textContent = 'Tloušťka stěny (s)';
        else if (k === 'd2') th.textContent = 'Průměr rýhování (d2)';
        else if (k === 'tol') th.textContent = 'Tolerance';
        else if (k === 'c') th.textContent = 'Zkosení (c)';
        else if (k === 'kuzel') th.textContent = 'Kuželovitost';
        else if (k === 'typ') th.textContent = 'Typ dílu';
        else if (k === 'zavit') th.textContent = 'Závit';
        else if (k === 'delka') th.textContent = 'Délka';
        else if (k === 'serie') th.textContent = 'Min. série';
        else if (k === 'prumer') th.textContent = 'Průměr';
        else if (k === 'dutina') th.textContent = 'Dutina';
        else th.textContent = k.toUpperCase();
        headerTr.appendChild(th);
      });
      modalTableHead.appendChild(headerTr);

      item.specs.forEach(function(row) {
        const tr = document.createElement('tr');
        keys.forEach(function(k) {
          const td = document.createElement('td');
          td.textContent = row[k] || '-';
          tr.appendChild(td);
        });
        modalTableBody.appendChild(tr);
      });
    }

    modalBackdrop.classList.add('active');
    modalBackdrop.setAttribute('aria-hidden', 'false');
    document.body.style.overflow = 'hidden';
  }

  function closeTechModal() {
    modalBackdrop.classList.remove('active');
    modalBackdrop.setAttribute('aria-hidden', 'true');
    document.body.style.overflow = '';
  }

  document.querySelectorAll('.catalog-item').forEach(function(card) {
    card.addEventListener('click', function(e) {
      const pid = card.getAttribute('data-open-tech');
      if (pid) {
        openTechModal(pid);
      }
    });
  });

  if (modalClose) modalClose.addEventListener('click', closeTechModal);
  if (modalCloseSecondary) modalCloseSecondary.addEventListener('click', closeTechModal);
  if (modalBackdrop) {
    modalBackdrop.addEventListener('click', function(e) {
      if (e.target === modalBackdrop) closeTechModal();
    });
  }

  if (modalPoptatBtn) {
    modalPoptatBtn.addEventListener('click', function() {
      closeTechModal();
    });
  }

  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape' && modalBackdrop.classList.contains('active')) {
      closeTechModal();
    }
  });

  const inquiryForm = document.getElementById('inquiryForm');
  const formSuccess = document.getElementById('formSuccess');
  if (inquiryForm) {
    inquiryForm.addEventListener('submit', function(e) {
      e.preventDefault();
      if (formSuccess) {
        formSuccess.style.display = 'block';
        inquiryForm.reset();
        setTimeout(function() {
          formSuccess.style.display = 'none';
        }, 6000);
      }
    });
  }

  const params = new URLSearchParams(window.location.search);
  if (params.get('ref') === 'nabidka') {
    const topbar = document.querySelector('.topbar-inner');
    if (topbar) {
      const greeting = document.createElement('span');
      greeting.className = 'topbar-chip';
      greeting.style.color = '#38bdf8';
      greeting.style.fontWeight = 'bold';
      greeting.textContent = 'Exkluzivní technologická nabídka modernizace B2B webu';
      topbar.prepend(greeting);
    }
  }
});